mod tests {
    use super::*;
    use callisto_model::vcs::VcsError;

    /// An unreadable pre-release state file names the path it was read from, not a hardcoded `.changeset/pre.json`.
    #[test]
    fn pre_json_read_error_names_the_real_path() {
        let error = GraphError::PreJsonRead {
            path: std::path::PathBuf::from("/repo/changes/pre.json"),
            message: "Is a directory (os error 21)".to_owned(),
        };
        let text = error.to_string();
        assert!(text.contains("/repo/changes/pre.json"), "got: {text}");
        assert!(!text.contains(".changeset/pre.json"), "got: {text}");
    }

    /// Spec: GraphError::Vcs must be transparent — wrapping a VcsError must
    /// not add any prefix (e.g. "vcs error: ") to the display message.
    #[test]
    fn graph_error_vcs_is_transparent_no_prefix() {
        let inner = VcsError::Git("some git error".to_string());
        let expected_msg = format!("{inner}");
        let graph_err = GraphError::Vcs(inner);
        assert_eq!(
            format!("{graph_err}"),
            expected_msg,
            "GraphError::Vcs must be transparent (no 'vcs error: ' prefix)"
        );
    }

    /// `GraphError::Command` must be transparent so the inner `CommandError`'s own code (e.g. E025) reaches
    /// `miette::Diagnostic::code` on the outer error.
    #[test]
    fn graph_error_command_surfaces_the_inner_commanderrors_own_code() {
        let inner = callisto_model::CommandError::TimedOut {
            program: "gh".to_string(),
            seconds: 60,
        };
        let graph_err = GraphError::Command(inner);
        assert_eq!(
            miette::Diagnostic::code(&graph_err)
                .map(|code| code.to_string())
                .as_deref(),
            Some("E025")
        );
        assert!(miette::Diagnostic::help(&graph_err).is_some());
    }

    /// Same for `GraphError::VersionParse`.
    #[test]
    fn graph_error_version_parse_surfaces_the_inner_errors_own_code() {
        let inner =
            callisto_model::Version::parse("not-a-version", callisto_model::VersionGrammar::SemVer).unwrap_err();
        let graph_err = GraphError::VersionParse(inner);
        assert!(miette::Diagnostic::code(&graph_err).is_some());
    }

    #[test]
    fn partial_version_run_help_explains_safe_manual_recovery() {
        let error = GraphError::PartialVersionRun {
            path: PathBuf::from("Cargo.toml"),
            disk: callisto_model::Version::parse("1.1.0", callisto_model::VersionGrammar::SemVer).unwrap(),
            index: "1.1.0".to_string(),
            head: callisto_model::Version::parse("1.0.0", callisto_model::VersionGrammar::SemVer).unwrap(),
        };
        let help = miette::Diagnostic::help(&error).unwrap().to_string();
        assert!(help.contains("git diff --cached"));
        assert!(help.contains("retained changeset or pre-state input"));
        assert!(help.contains("git rm -- <path>"));
    }

    /// ConflictingPlatformTargetSources must name the
    /// package and both source field names in its Display text, and carry
    /// diagnostic code E118 with help text pointing at the fix.
    #[test]
    fn conflicting_platform_target_sources_message_names_package_and_both_sources() {
        use callisto_model::PackageId;

        let err = GraphError::ConflictingPlatformTargetSources {
            package: PackageId::Bare("native-mod".to_string()),
            napi_source: "napi.targets",
            maturin_source: "[tool.maturin].targets",
        };
        let msg = format!("{err}");
        assert!(msg.contains("native-mod"), "message must name the package: {msg}");
        assert!(msg.contains("napi.targets"), "message must name napi_source: {msg}");
        assert!(
            msg.contains("[tool.maturin].targets"),
            "message must name maturin_source: {msg}"
        );
    }
}

