impl GraphError {
    /// E102 for `id`, suggesting up to three of `known` whose names are a small edit away.
    pub fn unknown_package(id: PackageId, known: impl IntoIterator<Item = PackageId>) -> Self {
        let hint = did_you_mean(&id, known);
        Self::UnknownPackage { id, hint }
    }

    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Config(error) => error.path(),
            Self::ParseChangeset { path, .. }
            | Self::UnexpectedManifestVersion { path, .. }
            | Self::PartialVersionRun { path, .. }
            | Self::ApplyIo { path, .. }
            | Self::UnsafeArtifactPath { path, .. }
            | Self::ArtifactRead { path, .. }
            | Self::ArtifactBytesMismatch { path }
            | Self::ArtifactAttestation { path, .. }
            | Self::ReleaseInputRead { path, .. }
            | Self::ReleaseDecisionDecode { path, .. }
            | Self::InitAlreadyInitialized { path }
            | Self::InitIo { path, .. }
            | Self::InitWorkflowExists { path } => Some(path),
            _ => None,
        }
    }
}

impl ConfigError {
    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Read { path, .. }
            | Self::ParseToml { path, .. }
            | Self::UnknownField { path, .. }
            | Self::InvalidValue { path, .. }
            | Self::InvalidPublishTarget { path, .. }
            | Self::InvalidReleaseTrigger { path, .. }
            | Self::InvalidCascadeMode { path, .. }
            | Self::InvalidChangelogLayout { path, .. }
            | Self::InvalidRegistryKind { path, .. }
            | Self::RegistryPublishUrlNotPypi { path, .. }
            | Self::CargoRegistryUrl { path, .. }
            | Self::InvalidRegistryTimeout { path, .. }
            | Self::InvalidPackageMatch { path, .. } => Some(path),
            _ => None,
        }
    }

    /// Rejects a colon-qualified package reference (`cargo:foo`); the slash form (`cargo/foo`) is the only qualified spelling.
    pub fn reject_colon_form(raw: &str, context: &str) -> Result<(), Self> {
        match PackageId::colon_form_canonical(raw) {
            Some(canonical) => Err(Self::ColonReference {
                context: context.to_owned(),
                given: raw.to_owned(),
                canonical,
            }),
            None => Ok(()),
        }
    }

    /// Requires the canonical `eco/name` form: the colon form is E316 and a name without an ecosystem is E317.
    pub fn require_qualified(raw: &str, context: &str) -> Result<(), Self> {
        Self::require_prefixed(raw, context, |eco| eco.is_some())
    }

    /// Like [`Self::require_qualified`], but the ecosystem must be one of cargo, npm or pypi.
    pub fn require_canonical_ecosystem(raw: &str, context: &str) -> Result<(), Self> {
        Self::require_prefixed(raw, context, |eco| {
            eco.is_some_and(|e| Ecosystem::CANONICAL.contains(&e))
        })
    }

    fn require_prefixed(raw: &str, context: &str, accepts: impl Fn(Option<Ecosystem>) -> bool) -> Result<(), Self> {
        Self::reject_colon_form(raw, context)?;
        let qualified = raw
            .split_once('/')
            .is_some_and(|(prefix, rest)| accepts(Ecosystem::from_prefix(prefix)) && !rest.is_empty());
        if qualified {
            return Ok(());
        }
        Err(Self::BareReference {
            context: context.to_owned(),
            given: raw.to_owned(),
        })
    }
}

#[cfg(test)]
mod redaction_tests {
    use super::*;

    /// A failing registry client echoes the token it was handed. That stderr
    /// reaches a miette diagnostic, `--format json`, and the CI step summary
    /// through this `Display`, so the credential must not survive it -- for
    /// every env var name the release path actually passes.
    #[test]
    fn non_zero_exit_display_redacts_release_path_credentials() {
        for (name, secret) in [
            ("CARGO_REGISTRY_TOKEN", "cio-secret-token-value"),
            ("GH_TOKEN", "ghp-secret-token-value"),
            ("NPM_TOKEN", "npm-secret-token-value"),
        ] {
            let rendered = temp_env::with_var(name, Some(secret), || {
                GraphError::ReleaseCommand {
                    program: "cargo".to_owned(),
                    args: vec!["publish".to_owned()],
                    failure: CommandFailure::NonZeroExit {
                        exit_code: Some(1),
                        stderr: format!("error: failed to authenticate with token {secret}\n"),
                    },
                }
                .to_string()
            });
            assert!(
                !rendered.contains(secret),
                "{name} value survived into the diagnostic: {rendered}"
            );
            assert!(
                rendered.contains("[REDACTED]"),
                "{name} value must be replaced by the redaction marker: {rendered}"
            );
            assert!(
                rendered.contains("failed to authenticate"),
                "redaction must keep the surrounding diagnostic text: {rendered}"
            );
        }
    }

    /// An authenticated remote URL is the leak shape that needs no env var to
    /// be set, so it is redacted independently of the token list.
    #[test]
    fn non_zero_exit_display_redacts_url_userinfo() {
        let failure = CommandFailure::NonZeroExit {
            exit_code: Some(128),
            stderr: "fatal: could not read from REDACTED".to_owned(),
        };
        let rendered = failure.to_string();
        assert!(!rendered.contains("REDACTED"), "userinfo survived: {rendered}");
    }
}

