    assert!(envelope["error"]["code"].is_string(), "{full:?}: {envelope}");
}

#[test]
fn every_failing_core_command_reports_its_own_name_and_dry_run() {
    let commands: [(&[&str], &str); 6] = [
        (&["status"], "status"),
        (&["version"], "version"),
